-- Example data for company-training user tests (invented @example.com accounts only).

-- Pre-launch checks: separate examples, never modify TESTI 2 Oy.
-- Traffic-light examples on the agent's previous test case, not the user's TESTI 2 Oy.

-- Isolated synthetic continuation checks; no sender or production account.
-- Independent same-Y-ID race examples and excluded personal case.

-- Yhteyshenkilöt 1C-A: several contacts per organization, same-named people, pagination and explicit offer/order links.
SELECT ('13000000-0000-4000-8000-0000000002' || lpad(g::text,2,'0'))::uuid,'12000000-0000-4000-8000-000000000020','Testihenkilö ' || lpad(g::text,2,'0'),'henkilo' || g || '@example.com', CASE WHEN g % 2 = 0 THEN '040 000 00' || lpad(g::text,2,'0') END, CASE WHEN g=5 THEN ARRAY['ai','safety'] WHEN g=6 THEN ARRAY['leadership'] ELSE '{}'::text[] END, CASE WHEN g=5 THEN now()-interval '30 days' WHEN g=6 THEN now()-interval '400 days' END, CASE WHEN g IN (5,6) THEN '10000000-0000-4000-8000-000000000001'::uuid END
FROM generate_series(1,27) g ON CONFLICT DO NOTHING;

-- Yhteyshenkilöt 1C-B: titles, organisation-scoped roles, key person and interests for a few synthetic contacts; others stay without details.

-- Order safety: wholly invented customers, accepted-offer fixtures approved by test staff only.
-- Fresh, disposable acceptance pools for repeatable checks; no real customer identities.
SELECT ('24000000-0000-4000-8000-'||lpad(g::text,12,'0'))::uuid,'Esimerkki '||g,'tilaaja.safety@example.com','Synteettinen Hoiva TESTI Oy','Teams-palaveri','Synteettinen vakautuskoe, ei viestejä','testi','kartoitus tehty','osaaminen','10000000-0000-4000-8000-000000000001'::uuid,'22000000-0000-4000-8000-000000000001'::uuid,'23000000-0000-4000-8000-000000000001'::uuid FROM generate_series(200,429) g WHERE g%100<30 ON CONFLICT DO NOTHING;
SELECT ('25000000-0000-4000-8000-'||lpad(g::text,12,'0'))::uuid,('24000000-0000-4000-8000-'||lpad(g::text,12,'0'))::uuid,'TESTI '||g||' – 2 h Teams-aseptiikka',900,100,'2026-11-27'::date,'accepted','10000000-0000-4000-8000-000000000001'::uuid FROM generate_series(200,429) g WHERE g%100<30 ON CONFLICT DO NOTHING;
SELECT ('26000000-0000-4000-8000-'||lpad(g::text,12,'0'))::uuid,('25000000-0000-4000-8000-'||lpad(g::text,12,'0'))::uuid,1,'22000000-0000-4000-8000-000000000001'::uuid,'23000000-0000-4000-8000-000000000001'::uuid,'osaaminen','2 h Teams-aseptiikkakoulutus',25.5,'yleinen','2026-11-26'::date,'2026-11-27'::date,'Synteettiset sopimusehdot','14 päivää netto','end' FROM generate_series(200,429) g WHERE g%100<30 ON CONFLICT DO NOTHING;
SELECT v.id,1,'2 h Teams-aseptiikkakoulutus',1,900 FROM public.crm_offer_versions v WHERE v.id::text LIKE '26000000-0000-4000-8000-%' AND v.approved_at IS NULL AND NOT EXISTS(SELECT 1 FROM public.crm_offer_version_lines l WHERE l.version_id=v.id);
-- Multi-delivery deduplication fixture for server-created synthetic orders only.
SELECT ('28000000-0000-4000-8000-'||lpad((x.g)::text,12,'0'))::uuid,o.id,'yrityskoulutus_tilaus','Synteettinen monen toteutuksen koe '||x.g,'10000000-0000-4000-8000-000000000002'::uuid,'10000000-0000-4000-8000-000000000001'::uuid FROM public.crm_orders o CROSS JOIN (VALUES(1),(2)) x(g) WHERE o.source_offer_version_id='26000000-0000-4000-8000-000000000114'::uuid ON CONFLICT DO NOTHING;
-- Concurrent offer approval: newer accepted version blocks stale source confirmation.
SELECT ('27000000-0000-4000-8000-'||lpad(g::text,12,'0'))::uuid,('25000000-0000-4000-8000-'||lpad(g::text,12,'0'))::uuid,2,'22000000-0000-4000-8000-000000000001'::uuid,'23000000-0000-4000-8000-000000000001'::uuid,'osaaminen','Uudempi 2 h Teams-koulutus',25.5,'yleinen','2026-11-26'::date,'2026-11-27'::date,'Synteettiset sopimusehdot','14 päivää netto','end' FROM (VALUES(124),(224),(324),(424)) x(g) ON CONFLICT DO NOTHING;
SELECT v.id,1,'Uudempi 2 h Teams-koulutus',1,900 FROM public.crm_offer_versions v WHERE v.id::text LIKE '27000000-0000-4000-8000-%' AND v.approved_at IS NULL AND NOT EXISTS(SELECT 1 FROM public.crm_offer_version_lines l WHERE l.version_id=v.id);
